'use client';

import * as React from 'react';
import { motion, type Variants } from 'motion/react';

import {
  getVariants,
  useAnimateIconContext,
  IconWrapper,
  type IconProps,
} from '@/components/animate-ui/icons/icon';

type AlignVerticalDistributeCenterProps = IconProps<keyof typeof animations>;

const animations = {
  default: {
    b1: {
      initial: { x: 0 },
      animate: {
        x: [0, 2, 0],
        transition: { duration: 0.9, times: [0, 0.45, 1], ease: 'easeInOut' },
      },
    },
    b2: {
      initial: { x: 0 },
      animate: {
        x: [0, -2, 0],
        transition: { duration: 0.9, times: [0, 0.45, 1], ease: 'easeInOut' },
      },
    },
    t1l: {
      initial: { d: 'M7 7H2' },
      animate: {
        d: ['M7 7H2', 'M9 7H2', 'M7 7H2'],
        transition: { duration: 0.9, times: [0, 0.45, 1], ease: 'easeInOut' },
      },
    },
    t1r: {
      initial: { d: 'M22 7h-5' },
      animate: {
        d: ['M22 7h-5', 'M22 7h-3', 'M22 7h-5'],
        transition: { duration: 0.9, times: [0, 0.45, 1], ease: 'easeInOut' },
      },
    },
    t2l: {
      initial: { d: 'M5 17H2' },
      animate: {
        d: ['M5 17H2', 'M3 17H2', 'M5 17H2'],
        transition: { duration: 0.9, times: [0, 0.45, 1], ease: 'easeInOut' },
      },
    },
    t2r: {
      initial: { d: 'M22 17h-3' },
      animate: {
        d: ['M22 17h-3', 'M22 17h-5', 'M22 17h-3'],
        transition: { duration: 0.9, times: [0, 0.45, 1], ease: 'easeInOut' },
      },
    },
  } satisfies Record<string, Variants>,
} as const;

function IconComponent({ size, ...props }: AlignVerticalDistributeCenterProps) {
  const { controls } = useAnimateIconContext();
  const variants = getVariants(animations);

  return (
    <motion.svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={2}
      strokeLinecap="round"
      strokeLinejoin="round"
      initial="initial"
      animate={controls}
      {...props}
    >
      <motion.path
        d="M22 17h-3"
        variants={variants.t2r}
        initial="initial"
        animate={controls}
      />
      <motion.path
        d="M22 7h-5"
        variants={variants.t1r}
        initial="initial"
        animate={controls}
      />
      <motion.path
        d="M5 17H2"
        variants={variants.t2l}
        initial="initial"
        animate={controls}
      />
      <motion.path
        d="M7 7H2"
        variants={variants.t1l}
        initial="initial"
        animate={controls}
      />
      <motion.rect
        x="5"
        y="14"
        width="14"
        height="6"
        rx="2"
        variants={variants.b2}
        initial="initial"
        animate={controls}
      />
      <motion.rect
        x="7"
        y="4"
        width="10"
        height="6"
        rx="2"
        variants={variants.b1}
        initial="initial"
        animate={controls}
      />
    </motion.svg>
  );
}

function AlignVerticalDistributeCenter(
  props: AlignVerticalDistributeCenterProps,
) {
  return <IconWrapper icon={IconComponent} {...props} />;
}

export {
  animations,
  AlignVerticalDistributeCenter,
  AlignVerticalDistributeCenter as AlignVerticalDistributeCenterIcon,
  type AlignVerticalDistributeCenterProps,
  type AlignVerticalDistributeCenterProps as AlignVerticalDistributeCenterIconProps,
};
